#[derive(Default)]struct Node{c:[Option<Box<Node>>;26],end:bool}struct Trie{r:Node}impl Trie{fn new()->Self{Self{r:Node::default()}}fn insert(&mut self,w:String){let mut p=&mut self.r;for b in w.bytes(){p=p.c[(b-b'a')as usize].get_or_insert_with(||Box::new(Node::default()));}p.end=true;}fn search(&self,w:String)->bool{let mut p=&self.r;for b in w.bytes(){if let Some(x)=p.c[(b-b'a')as usize].as_ref(){p=x}else{return false}}p.end}fn starts_with(&self,w:String)->bool{let mut p=&self.r;for b in w.bytes(){if let Some(x)=p.c[(b-b'a')as usize].as_ref(){p=x}else{return false}}true}}
